INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9ebf-c0d2-7459-98ef-aad8dc14a00a'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'Two exchange rates are given: 1 USD = SGD x in 2023, and in 2022 the rate was SGD 0.030 less per USD. The difference in exchanging SGD 10 000 between the two years is USD 166. Write down the equation in x.', '10000/x - 10000/(x - 0.030) = 166', 'In 2023, 10 000 SGD gives 10000/x USD. In 2022, 10 000 SGD gives 10000/(x - 0.030) USD. Their difference is 166 USD, so 10000/x - 10000/(x - 0.030) = 166.', 'Medium', '{"tags":"ratio,exchange-rates,algebra","subtopic":"exchange rates","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T14:06:34.706Z'::timestamptz, '2026-07-26T14:06:34.706Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9ebf-c0da-7813-b431-055592fa6664'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Show that (7n - 1)^2 - (n - 1)^2 is a multiple of 12 for all integer values of n.', '12n(4n - 1)', 'Use the difference of two squares: (7n - 1)^2 - (n - 1)^2 = [(7n - 1) + (n - 1)] [(7n - 1) - (n - 1)] = (8n - 2)(6n). This simplifies to 12n(4n - 1), which is always divisible by 12.', 'Medium', '{"tags":"numbers,proof,algebra","subtopic":"multiple of 12","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T14:06:34.714Z'::timestamptz, '2026-07-26T14:06:34.714Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9ebf-c0de-7550-b119-103e3c4ba23a'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Simplify (p - 3n)(4n - 1) / [12n(4n - 1)].', '(3n - p)/(12n)', 'Cancel the common factor (4n - 1) from numerator and denominator. Since p - 3n = -(3n - p), the expression becomes (3n - p)/(12n).', 'Medium', '{"tags":"algebra,fractions,simplification","subtopic":"algebraic fractions","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T14:06:34.718Z'::timestamptz, '2026-07-26T14:06:34.718Z'::timestamptz) ON CONFLICT (id) DO NOTHING;